/**
 * Exercise → muscle mapping audit (2026-11-22, FIX_PLAN.md E.11). One entry per exercise in src/data/exercises.ts:
 * verdict (verified / corrected / uncertain), confidence, the coefficients the library now uses (checked by
 * tests/exercise-audit.test.ts), the previous values when corrected, muscles that act only as STABILISERS (not
 * credited, or at most 0.25), rationale, evidence ids (references*.ts), limitations and variation notes.
 * Evidence hierarchy: longitudinal hypertrophy trials / reviews > biomechanics > EMG (indirect only). Where
 * evidence was insufficient the verdict is 'uncertain' and the value was kept, never invented.
 * The coefficients themselves live ONLY in src/data/exercises.ts (single source of truth); this file documents them.
 */
import type { MuscleId } from '../../domain/types';

export interface ExerciseAudit {
  id: string;
  group: 'push' | 'pull' | 'legs' | 'core';
  verdict: 'verified' | 'corrected' | 'uncertain';
  confidence: 'high' | 'moderate' | 'low';
  coefficients: Partial<Record<MuscleId, number>>;
  previous: Partial<Record<MuscleId, number>> | null;
  stabilizers: MuscleId[];
  rationale: string;
  refIds: string[];
  limitations: string;
  variationNotes: string;
}

